  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\ngenerator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"debian-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:./dev.db\"\n}\n\nmodel User {\n  id                 String              @id @default(cuid())\n  username           String              @unique\n  password           String\n  isAdmin            Boolean             @default(false)\n  isBanned           Boolean             @default(false)\n  banReason          String?\n  banExpiresAt       DateTime?\n  createdAt          DateTime            @default(now())\n  updatedAt          DateTime            @updatedAt\n  words              Word[]\n  reviewGroups       ReviewGroup[]\n  securityViolations SecurityViolation[]\n}\n\nmodel Word {\n  id                 String   @id @default(cuid())\n  word               String // Removed @unique so different users can have the same word\n  phonetic           String? // 音标，可选\n  pos                String? // 词性，可选\n  translation        String // 中文翻译\n  example            String? // 英文例句\n  exampleTranslation String? // 例句翻译\n  correctCount       Int      @default(0) // 默写答对次数\n  incorrectCount     Int      @default(0) // 默写答错次数\n  createdAt          DateTime @default(now()) // 创建时间\n  updatedAt          DateTime @updatedAt // 更新时间\n\n  userId           String\n  user             User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  reviewGroupWords ReviewGroupWord[]\n\n  @@unique([word, userId]) // Ensures a specific user doesn't add the same word twice\n}\n\n// 用户创建的复习分组（最多3个，无单词数量限制）\nmodel ReviewGroup {\n  id        String            @id @default(cuid())\n  name      String // 分组名称\n  userId    String\n  user      User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  words     ReviewGroupWord[]\n  createdAt DateTime          @default(now())\n  updatedAt DateTime          @updatedAt\n\n  @@unique([name, userId]) // 同一用户不能有同名分组\n}\n\n// 复习分组和单词的关联表 (多对多关系)\nmodel ReviewGroupWord {\n  id            String   @id @default(cuid())\n  reviewGroupId String\n  wordId        String\n  addedAt       DateTime @default(now())\n\n  reviewGroup ReviewGroup @relation(fields: [reviewGroupId], references: [id], onDelete: Cascade)\n  word        Word        @relation(fields: [wordId], references: [id], onDelete: Cascade)\n\n  @@unique([reviewGroupId, wordId]) // 一个单词在同一个分组中只能出现一次\n}\n\n// 全局公共词库，用于缓存 AI 解析结果和作为公共复习来源\nmodel PublicWord {\n  id                 String   @id @default(cuid())\n  word               String   @unique // 公共词库中每个单词唯一\n  phonetic           String?\n  pos                String?\n  translation        String\n  example            String?\n  exampleTranslation String?\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n}\n\n// 全局 API 配置（仅存一条记录）\nmodel ApiConfig {\n  id           String   @id @default(\"global\") // 锁定 ID 为 \"global\" 确保只有一条\n  apiKey       String\n  baseUrl      String   @default(\"https://api.openai.com/v1/chat/completions\")\n  model        String   @default(\"gpt-4o-mini\")\n  systemPrompt String? // 自定义系统提示词（软编码）\n  updatedAt    DateTime @updatedAt\n}\n\n// 安全违规记录\nmodel SecurityViolation {\n  id            String   @id @default(cuid())\n  userId        String\n  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  violationType String // \"PROMPT_INJECTION\", \"RATE_LIMIT_ABUSE\", etc.\n  inputValue    String // 用户输入的内容（截断）\n  detectedAt    DateTime @default(now())\n  ipAddress     String?\n  userAgent     String?\n\n  @@index([userId])\n  @@index([detectedAt])\n}\n\n// IP封禁记录\nmodel IpBan {\n  id             String    @id @default(cuid())\n  ipAddress      String    @unique\n  reason         String\n  violationCount Int       @default(1)\n  bannedAt       DateTime  @default(now())\n  expiresAt      DateTime?\n  isPermanent    Boolean   @default(false)\n\n  @@index([ipAddress])\n}\n",
